L,W,H=52.4+.5,27.2+.5,24+.5;pinmin,pinmax=3.5-1,3.5+1;side,bottom=10,5;coreID,wall=43,2.5
assert (L,W,H)==(52.9,27.7,24.5) and (pinmin,pinmax)==(2.5,4.5)
# Necessary lateral-plane lower bound: maximum possible chord in the unmodified bore is43.
width_required=W+2*side;assert width_required>coreID
# Separate rectangular reservation constructions; not an optimized enclosing-circle or end-product certification.
def reservation(name,length,width,height,assumption):
 return {'name':name,'length_width_height_mm':[length,width,height],'rectangular_cross_section_diagonal_mm':math.hypot(width,height),'same2p5wall_OD_comparison_mm':math.hypot(width,height)+2*wall,'assumption':assumption}
boxes=[reservation('body-face-only comparison',L+20,W+20,H+5+10,'10mm on both X/Y sides and above,5mm below BODY face; excludes pins as clearance datum, carrier, film and tolerances. Upper10mm is an explicitly conservative interpretation of around, not a separately stated top clause.'),reservation('max-pin-referenced module reservation',L+20,W+20,H+pinmax+5+10,'Same side/top reservation,5mm beyond lowest maximum live pin; board/copper stay above that pin in R1. This conservative bottom datum is not asserted to be defined in the manual.'),reservation('same reservation plus illustrative R1 film thickness',L+20,W+20,H+pinmax+5+10+.125,'Adds R1 unqualified .125mm film outside full5mm separation; guide specifies neither film thickness nor permission to subtract it from5mm.'),reservation('carrier+pin assembly planning reservation',61+20,32+20,H+pinmax+5+10,'Conservative whole carrier61x32 planning box with same allowances. Treating the carrier as part of unit assembly is an engineering reservation, not a manufacturer-specified construction or approved minimum. Retention, trunk, endcaps, leads and cooling may require more.')]
